/**
 * Creates a Chrome Web Store-ready zip from the dist/ folder.
 * Excludes TypeScript declaration files (.d.ts) that are generated by tsc
 * but are unnecessary for the extension package.
 *
 * Usage: node scripts/package-extension.js
 * Output: wavelink-<version>.zip
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const manifest = JSON.parse(fs.readFileSync('dist/manifest.json', 'utf8'));
const version = manifest.version;
const outFile = `wavelink-${version}.zip`;

// Collect all files from dist/, excluding .d.ts and .d.ts.map files
function collectFiles(dir, base = dir) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  const files = [];
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...collectFiles(full, base));
    } else if (!entry.name.endsWith('.d.ts') && !entry.name.endsWith('.d.ts.map')) {
      files.push(path.relative(base, full));
    }
  }
  return files;
}

if (!fs.existsSync('dist')) {
  console.error('Error: dist/ not found. Run `npm run build` first.');
  process.exit(1);
}

const files = collectFiles('dist');
console.log(`Packaging ${files.length} files into ${outFile}...`);

// Use PowerShell's Compress-Archive on Windows, or zip on Unix
const fileList = files.map(f => `dist/${f.replace(/\\/g, '/')}`).join(' ');

try {
  if (process.platform === 'win32') {
    // Build list of files for PowerShell
    const psFileList = files.map(f => `'dist\\${f.replace(/\//g, '\\')}' `).join(',');
    if (fs.existsSync(outFile)) fs.unlinkSync(outFile);
    execSync(
      `powershell -Command "Compress-Archive -Path ${psFileList} -DestinationPath '${outFile}'"`,
      { stdio: 'inherit' }
    );
  } else {
    if (fs.existsSync(outFile)) fs.unlinkSync(outFile);
    execSync(`zip -r ${outFile} dist/ --exclude "dist/src/*"`, { stdio: 'inherit' });
  }
  const size = (fs.statSync(outFile).size / 1024).toFixed(1);
  console.log(`\nCreated ${outFile} (${size} KB)`);
  console.log('Upload this file to the Chrome Web Store developer dashboard.');
} catch (err) {
  console.error('Packaging failed:', err.message);
  process.exit(1);
}
